# TICKET-12: Invoice export

Requested by: Finance lead, 2026-10-10

Finance needs to download invoices as a spreadsheet for the monthly close.
Only the last 12 months are needed; older invoices are archived elsewhere.
// Invoice rules. Amounts are integer cents.
export const STATUSES = ["draft", "sent", "paid", "void"];

export function invoiceTotal(invoice) {
  return invoice.lines.reduce((sum, line) => sum + line.quantity * line.unitPriceCents, 0);
}

export function changeStatus(invoice, next, actor) {
  if (!STATUSES.includes(next)) throw new Error(`unknown status ${next}`);
  if (invoice.status === "void") throw new Error("void invoices cannot change");
  if (next === "void" && actor.role !== "admin") throw new Error("only admins can void invoices");
  return { ...invoice, status: next };
}

export function listInvoices(invoices, { orgId }) {
  return invoices.filter((invoice) => invoice.orgId === orgId);
}
import http from "node:http";
import { listInvoices, invoiceTotal } from "./invoices.js";

const invoices = [];

const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://localhost");
  if (req.method === "GET" && url.pathname === "/invoices") {
    const orgId = req.headers["x-org-id"];
    if (!orgId) {
      res.writeHead(401).end();
      return;
    }
    const rows = listInvoices(invoices, { orgId }).map((i) => ({ ...i, totalCents: invoiceTotal(i) }));
    res.writeHead(200, { "content-type": "application/json" }).end(JSON.stringify(rows));
    return;
  }
  res.writeHead(404).end();
});

if (process.argv[1] && process.argv[1].endsWith("server.js")) {
  server.listen(process.env.PORT || 3000);
}

export default server;
import { test } from "node:test";
import assert from "node:assert/strict";
import { invoiceTotal, changeStatus, listInvoices } from "../src/invoices.js";

const invoice = { id: "inv-1", orgId: "org-a", status: "draft", lines: [{ quantity: 2, unitPriceCents: 1500 }] };

test("total sums line amounts", () => {
  assert.equal(invoiceTotal(invoice), 3000);
});

test("only admins can void", () => {
  assert.throws(() => changeStatus(invoice, "void", { role: "member" }));
  assert.equal(changeStatus(invoice, "void", { role: "admin" }).status, "void");
});

test("list is scoped to the caller's org", () => {
  const rows = listInvoices([invoice, { ...invoice, id: "inv-2", orgId: "org-b" }], { orgId: "org-a" });
  assert.deepEqual(rows.map((r) => r.id), ["inv-1"]);
});
